// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 t, address actor) public {
        t = bound(t, 1, type(uint256).max - 2);
        vm.assume(actor != address(c));
        vm.roll(1); // not a multiple of 15, so no transfer side effects
        vm.warp(t);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        assertEq(c.pastBlockTime(), t);
        assertTrue(c.pastBlockTime() == t);
    }
}
